/** Einstellungen › „Hell oder Dunkel“ (D75): three radio rows, the whole row is the target; words from sbMessages(). */
@Composable
fun SbThemeChoice(mode: SbThemeMode, onChange: (SbThemeMode) -> Unit, modifier: Modifier = Modifier) {
    val m = sbMessages()
    val options = listOf(
        SbThemeMode.System to m.themeSystem,
        SbThemeMode.Light to m.themeLight,
        SbThemeMode.Dark to m.themeDark,
    )
    SbRadioChoice(m.themeGroup, options, selected = mode, onChange = onChange, modifier = modifier)
}

