/**
 * A settings group of radio rows: [title] (label, text, a heading), then one 56 dp row per option, radio ring 20 dp
 * (2 dp borderStrong; chosen: ring and 10 dp dot in accent, label bodyStrong), the whole row is the target.
 * SbThemeChoice and SbToneChoice (§12.1) are built on it. [title] null (spec/02 §4.7): no group title, for a choice under a
 * head that already names it (SbBottomSheet(title = …), §14.1), so the word is not said twice. [help] (§12) = a
 * second calm line under an option's word (caption, textMuted); [error] (spec/02 §2.4) = the group's error under the rows,
 * as a field's (glyph and sentence); TalkBack reads the sentence after the rows and says it once when it appears.
 */
@Composable
fun <T> SbRadioChoice(
    title: String?,
    options: List<Pair<T, String>>,
    selected: T,
    onChange: (T) -> Unit,
    modifier: Modifier = Modifier,
    help: Map<T, String> = emptyMap(),
    error: String? = null,
    enabled: Boolean = true,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    Column(modifier.fillMaxWidth()) {
        if (title != null) {
            Text(
                title,
                style = ty.label,
                color = c.text,
                modifier = Modifier
                    .padding(horizontal = t.spacing.gutter, vertical = t.space.s2)
                    .semantics { heading() },
            )
        }
        Column(Modifier.selectableGroup()) {
            options.forEach { (value, label) ->
                SbRadioRow(label, value == selected, onClick = { onChange(value) }, help = help[value], enabled = enabled)
            }
        }
        if (error != null) {
            Column(Modifier.padding(horizontal = t.spacing.gutter, vertical = t.space.s1)) {
                SbFieldNotes(help = null, counter = null, error = error, spoken = true)
            }
        }
    }
}

/**
 * One radio row of [SbRadioChoice] and of the time sheet (§14.34): ≥ 56 dp, the 20 dp ring (chosen: ring and dot in
 * accent, the word at bodyStrong), [help] a calm second line, the whole row the target.
 */
@Composable
internal fun SbRadioRow(label: String, chosen: Boolean, onClick: () -> Unit, modifier: Modifier = Modifier, help: String? = null, enabled: Boolean = true) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val interaction = remember { MutableInteractionSource() }
    Row(
        modifier
            .fillMaxWidth()
            .sbFocusRingInset(interaction)
            .heightIn(min = t.size.controlLg)
            .selectable(
                selected = chosen,
                enabled = enabled,
                interactionSource = interaction,
                indication = null,
                role = Role.RadioButton,
                onClick = onClick,
            )
            .padding(horizontal = t.spacing.gutter, vertical = if (help != null) t.space.s2 else t.space.s0),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s3),
    ) {
        val ring = if (!enabled) c.border else if (chosen) c.accent else c.borderStrong
        Box(
            Modifier
                .size(t.size.iconMd)
                .border(2.dp, ring, t.shapes.pill)
                .padding(5.dp)
                .then(if (chosen) Modifier.background(if (enabled) c.accent else c.textMuted, t.shapes.pill) else Modifier),
        )
        if (help == null) {
            Text(label, style = if (chosen) ty.bodyStrong else ty.body, color = if (enabled) c.text else c.textMuted)
        } else {
            Column(verticalArrangement = Arrangement.spacedBy(t.space.s0_5)) {
                Text(label, style = if (chosen) ty.bodyStrong else ty.body, color = if (enabled) c.text else c.textMuted)
                Text(help, style = ty.caption, color = c.textMuted)
            }
        }
    }
}
